// 602 からの分析結果を受け取り、改善対象を整理
const analysis = $input.first().json;

const improvement_tasks = {
  success_patterns: analysis.success_patterns || [],
  improvements_needed: analysis.improvement_suggestions || [],
  low_performers: analysis.low_performers || [],
  period: analysis.period,
  state: 'IMPROVEMENT_PENDING'
};

return [{ json: improvement_tasks }];

// ライターエージェント向けの実行指示を生成
const tasks = $input.first().json;

const writer_prompt = `【投稿改善タスク】

期間: ${tasks.period}

## 成功パターン（次の投稿で活かすべき）
${tasks.success_patterns.map(p => `• ${p.pattern}: ${p.reason}`).join('
')}

## 改善が必要な投稿
${tasks.improvements_needed.map(i => `【${i.platform}】
改善内容: ${i.improvement}
新しい提案: ${i.new_title}
期待効果: ${i.expected_impact}`).join('

')}

## 実行内容
1. 低反応投稿の編集案を作成（見出し・段落構成・文体を修正）
2. 高反応投稿の成功パターンを分析して、パターンテンプレートを作成
3. 次週の投稿計画案を生成（成功パターンを反映）

## 出力形式
{
  "edits": [{"platform": "媒体", "original_title": "元のタイトル", "revised_title": "改善後", "reason": "改善理由"}],
  "success_template": {"pattern": "...", "structure": "...", "tone": "..."},
  "next_week_plan": [{"date": "YYYY-MM-DD", "platform": "媒体", "theme": "テーマ", "based_on_pattern": "どの成功パターンに基づくか"}]
}`;

const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 2048,
  messages: [{ role: 'user', content: writer_prompt }]
};

return [{ json: { ...tasks, anthropic_body, prompt: writer_prompt } }];

// Claude応答をパース
const claude_result = $('Claude: Generate Improvement Plan').first().json;
const tasks = $input.first().json;

let improvement_plan = null;
let parse_error = null;

try {
  if (claude_result?.content && claude_result.content[0]?.text) {
    const text = claude_result.content[0].text;
    const match = text.match(/\{[\s\S]*\}/);
    improvement_plan = JSON.parse(match ? match[0] : text);
  } else {
    parse_error = 'claude_response_missing';
  }
} catch (e) {
  parse_error = 'claude_parse_failed: ' + e.message;
}

if (parse_error) {
  improvement_plan = {
    error: parse_error,
    edits: [],
    success_template: { pattern: 'パース失敗' },
    next_week_plan: []
  };
}

return [{ json: {
  ...tasks,
  improvement_plan,
  errors: parse_error ? [parse_error] : [],
  state: 'READY_FOR_EXECUTION'
} }];

// Slack 投稿用に整形
const d = $input.first().json;
const plan = d.improvement_plan;

const lines = [
  '📝 【投稿改善実行計画】' + d.period,
  '',
  '✏️ 改善対象投稿',
  ...plan.edits.slice(0, 3).map(e => `  ${e.platform}: "${e.original_title}" → "${e.revised_title}"`),
  '',
  '🎯 成功パターンテンプレート',
  `  構成: ${plan.success_template.structure}`,
  `  文体: ${plan.success_template.tone}`,
  '',
  '📅 来週の投稿計画（成功パターンに基づく）',
  ...plan.next_week_plan.slice(0, 5).map(p => `  ${p.date} ${p.platform}: ${p.theme}`),
  '',
  '🔄 次のステップ: ライターが編集案を Google Docs に作成します。確認して実施してください。'
];

return [{ json: { ...d, notification_text: lines.join('\n') } }];

// 改善計画を Google Sheets に保存（トラッキング用）
const d = $input.first().json;

const tracking_data = {
  period: d.period,
  total_edits: d.improvement_plan.edits?.length || 0,
  next_posts: d.improvement_plan.next_week_plan?.length || 0,
  state: 'TRACKED',
  timestamp: new Date().toISOString()
};

return [{ json: { ...d, tracking_data } }];
